public class ArrayExample {
    public static void main(String[] args) {
        int[] ageList = new int[5];

        ageList[0] = 23;        // initialize elements using the assignment operator
        ageList[1] = 18;
        ageList[2] = 22;
        ageList[3] = 17;
        ageList[4] = 34;

        double[] prices = {12.25, 32.50, 16.90, 1.25, 43};   // initial values

        int index = 3;
        System.out.println(prices[index + 1]);               // 43.0
    }
}

int[] a = {1, 2, 3};
int[] b = a;          // b is another name for the same array
b[0] = 99;
System.out.println(a[0]);   // 99

int[] c = Arrays.copyOf(a, a.length);
c[1] = 50;
System.out.println(Arrays.toString(a));   // [99, 2, 3]
System.out.println(Arrays.toString(c));   // [99, 50, 3]
